// Table state: seats, dealer rotation, the running game and the records of finished games
// (docs/table.md §1, docs/statistics.md §1).

import type { GameAction, GameErrorCode, GameState, Role, Suit } from '../engine';

/** Uuid-like id generated by the host when a player joins. */
export type PlayerId = string;
export type BotLevel = 'easy' | 'normal' | 'strong';

export interface Player {
  readonly id: PlayerId;
  readonly name: string; // 1..20 chars, trimmed, unique at the table
  readonly connected: boolean;
  readonly isBot: boolean;
  /** Strength of a bot (docs/bots.md); absent for humans and read as 'normal' for bots. */
  readonly botLevel?: BotLevel;
  /** Left during a running game; removed at the next deal (docs/table.md §2). */
  readonly leaving?: boolean;
}

/** 'in-game' while a game is dealt, including a finished game that waits for "ready". */
export type TableStatus = 'lobby' | 'in-game';

export interface ActiveGame {
  readonly number: number; // 1-based, counts every dealt game
  readonly engine: GameState;
  readonly roles: Readonly<Record<Role, PlayerId>>;
  readonly sittingOut: readonly PlayerId[];
  readonly dealerId: PlayerId;
  readonly seed: number; // SECRET (host only)
  readonly seatsAtDeal: number; // N when dealt (Seeger bonus)
  readonly recorded: boolean; // the record of this game has been created
}

/** Table rules, changed by the host between games (docs/table.md §1, skat-rules §12). */
export interface TableRules {
  readonly ramsch: boolean; // Ramsch instead of a passed-in game
}

export interface TableState {
  readonly key: string;
  readonly name: string;
  readonly isPublic: boolean;
  readonly hostId: PlayerId;
  readonly maxSeats: number; // 6 for tables created in the UI; tests may use fewer
  readonly status: TableStatus;
  readonly players: readonly Player[]; // index = seat (clockwise)
  readonly pending: readonly Player[]; // joined while a game runs; seated after it
  readonly nextDealerIdx: number; // seat index of the NEXT dealer
  readonly gameCounter: number; // games dealt so far (incl. aborted)
  readonly game: ActiveGame | null;
  readonly ready: readonly PlayerId[]; // who pressed "continue" after the finished game
  readonly rules: TableRules;
  readonly records: readonly GameRecord[];
  readonly seq: number; // increments on every state change
}

/** Who takes a seat in `replace-player`: a player waiting at the table, or a new bot. */
export type ReplaceBy =
  | { readonly kind: 'pending'; readonly playerId: PlayerId }
  | { readonly kind: 'bot'; readonly level: BotLevel };

export type TableCommand =
  | { readonly type: 'start' }
  | { readonly type: 'game'; readonly action: GameAction }
  | { readonly type: 'ready' }
  | { readonly type: 'abort-game' }
  | { readonly type: 'kick'; readonly playerId: PlayerId }
  | { readonly type: 'replace-player'; readonly playerId: PlayerId; readonly by: ReplaceBy }
  | { readonly type: 'add-bot' }
  | { readonly type: 'set-bot-level'; readonly playerId: PlayerId; readonly level: BotLevel }
  | { readonly type: 'leave' }
  | { readonly type: 'set-rules'; readonly rules: TableRules };

/** Values supplied by the caller: wall clock (record timestamps) and the deal seed. */
export interface Ctx {
  readonly now: number;
  readonly seed: number;
}

export type TableErrorCode =
  | GameErrorCode
  | 'NOT_HOST'
  | 'NOT_SEATED'
  | 'NOT_ACTIVE_PLAYER'
  | 'WRONG_STATUS'
  | 'TOO_FEW_PLAYERS'
  | 'TABLE_FULL'
  | 'UNKNOWN_PLAYER'
  | 'GAME_RUNNING'
  | 'INVALID_NAME'
  | 'CANNOT_KICK_HOST'
  | 'NOT_A_BOT'
  | 'HOST_CANNOT_LEAVE';

export type GameKindLabel = 'clubs' | 'spades' | 'hearts' | 'diamonds' | 'grand' | 'null';

/** Score deltas per seated player id, for both scoring systems (skat-rules §10.5, §10.6). */
export interface ScoreDeltas {
  readonly standard: Readonly<Record<PlayerId, number>>;
  readonly seeger: Readonly<Record<PlayerId, number>>;
}

/** One record per finished game (played or passed in). Aborted games create no record. */
export interface GameRecord {
  readonly id: string; // `${tableKey}-${number}`
  readonly number: number;
  readonly timestamp: number; // ctx.now at finish
  readonly tableSize: number; // N seated players when dealt
  readonly dealerId: PlayerId;
  readonly roles: Readonly<Record<Role, PlayerId>>;
  readonly sittingOut: readonly PlayerId[];
  readonly names: Readonly<Record<PlayerId, string>>; // names at that time (survive kicks)
  readonly outcome: 'passed-in' | 'played' | 'ramsch';
  // below: only when outcome === 'played' (null otherwise)
  readonly declarerId: PlayerId | null;
  readonly bid: number | null;
  readonly game: GameKindLabel | null;
  readonly hand: boolean;
  readonly ouvert: boolean;
  readonly announce: 'none' | 'schneider' | 'schwarz';
  readonly spitzenWith: boolean | null;
  readonly spitzenCount: number | null;
  readonly multiplier: number | null;
  readonly gameValue: number | null;
  readonly declarerPoints: number | null; // null for Null games
  readonly defenderPoints: number | null;
  readonly declarerTricks: number | null;
  readonly schneider: boolean;
  readonly schwarz: boolean;
  readonly overbid: boolean;
  readonly won: boolean;
  readonly scores: ScoreDeltas;
  // only when outcome === 'ramsch' (null otherwise); all keyed by player id
  readonly ramsch: {
    readonly points: Readonly<Record<PlayerId, number>>;
    readonly tricks: Readonly<Record<PlayerId, number>>;
    readonly loserIds: readonly PlayerId[];
    readonly jungfrau: boolean;
    readonly durchmarschId: PlayerId | null;
  } | null;
}

/** Label of the suit trump used in statistics and history. */
export const SUIT_LABELS: Readonly<Record<Suit, GameKindLabel>> = {
  C: 'clubs',
  S: 'spades',
  H: 'hearts',
  D: 'diamonds',
};
